// Field Guide cards first taught in the J camp (The Balcony): TypeScript, React, tests.
// Accuracy notes: every tsc message below is real `tsc --noEmit --strict` output; React
// messages are real React 19 development-build output; node:test and Vitest output is real
// (timings trimmed). The game strips TypeScript types before running, so it never shows
// type errors itself: cards say so, and label real-computer output.

const TS_OS = {
  ubuntu: '**Ubuntu / Debian.** TypeScript installs through npm, so you need Node first (see the npm card if `node -v` fails). Then, inside your project folder:\n```\nnpm install --save-dev typescript\nnpx tsc --init\nnpx tsc --noEmit\n```\n`--init` writes a `tsconfig.json` (with `strict` turned on). Editors like VS Code (`sudo snap install code --classic`, or the .deb from the VS Code website) show TypeScript errors as red squiggles while you type.',
  fedora: '**Fedora.** Install Node with `sudo dnf install nodejs` if you haven\'t, then inside your project: `npm install --save-dev typescript`, `npx tsc --init`, `npx tsc --noEmit`. VS Code is available as an RPM from its website (or as a Flatpak).',
  arch: '**Arch.** `sudo pacman -S nodejs npm` if needed, then in your project: `npm install --save-dev typescript`, `npx tsc --init`, `npx tsc --noEmit`. (A system-wide `typescript` package exists too, but a per-project install keeps every project on the version it was written for.)',
  mac: '**macOS.** `brew install node` if `node -v` fails. Then in your project folder in Terminal: `npm install --save-dev typescript`, `npx tsc --init`, `npx tsc --noEmit`. VS Code (from its website, or `brew install --cask visual-studio-code`) shows the errors as you type.',
  windows: '**Windows.** Work inside your WSL Ubuntu terminal and follow the Ubuntu steps: `npm install --save-dev typescript`, `npx tsc --init`, `npx tsc --noEmit`. VS Code on Windows can open your WSL folders directly (install its WSL extension, then run `code .` inside Ubuntu).',
  chromeos: '**ChromeOS.** In the Linux development environment (Debian), install Node as on Ubuntu, then in your project: `npm install --save-dev typescript`, `npx tsc --init`, `npx tsc --noEmit`. VS Code has a Debian .deb you can install inside Linux.',
  phone: '**Phone.** You can\'t run `tsc` on an iPhone. On Android, Termux can (`pkg install nodejs`, then the npm steps). In this game your TypeScript runs with the types stripped and **nothing checks them**, which is why this camp shows you real `tsc` messages instead of "run it and see."',
  linux: '**Linux.** Install Node with your package manager (or nvm), then in your project: `npm install --save-dev typescript`, `npx tsc --init`, `npx tsc --noEmit`.',
}

const VITE_OS = {
  ubuntu: '**Ubuntu / Debian.** With Node installed:\n```\nnpm create vite@latest gear-app -- --template react-ts\ncd gear-app\nnpm install\nnpm run dev\n```\nOpen the `http://localhost:5173/` address it prints in your browser. `react-ts` gives you React with TypeScript; `--template react` is the plain JavaScript version. Press Ctrl+C in the terminal to stop the dev server. Vite needs Node 20.19 or newer (check with `node -v`).',
  fedora: '**Fedora.** Same commands as anywhere: `npm create vite@latest gear-app -- --template react-ts`, then `cd gear-app`, `npm install`, `npm run dev`, and open `http://localhost:5173/`. Vite needs Node 20.19 or newer (check with `node -v`).',
  arch: '**Arch.** `npm create vite@latest gear-app -- --template react-ts`, `cd gear-app`, `npm install`, `npm run dev`, then open `http://localhost:5173/`. Vite needs Node 20.19 or newer (check with `node -v`).',
  mac: '**macOS.** In Terminal: `npm create vite@latest gear-app -- --template react-ts`, `cd gear-app`, `npm install`, `npm run dev`. Cmd+click the `http://localhost:5173/` link it prints to open it. Vite needs Node 20.19 or newer (check with `node -v`).',
  windows: '**Windows.** Run the commands inside WSL Ubuntu: `npm create vite@latest gear-app -- --template react-ts`, `cd gear-app`, `npm install`, `npm run dev`. Your Windows browser can open `http://localhost:5173/` directly, because WSL forwards localhost. Keep the project inside your Linux home folder (not under `/mnt/c`), or file watching and reloads get slow. Vite needs Node 20.19 or newer (check with `node -v`).',
  chromeos: '**ChromeOS.** Inside the Linux environment: `npm create vite@latest gear-app -- --template react-ts`, `cd gear-app`, `npm install`, `npm run dev`. Chrome can open `http://localhost:5173/`, because ChromeOS forwards ports from Linux automatically. Vite needs Node 20.19 or newer (check with `node -v`).',
  phone: '**Phone.** You can\'t run a Vite dev server on an iPhone. In this game the React preview compiles your JSX for you. On a real project you\'d build on a computer, then open the dev server from your phone on the same network with `npm run dev -- --host`.',
  linux: '**Linux.** `npm create vite@latest gear-app -- --template react-ts`, `cd gear-app`, `npm install`, `npm run dev`, then open `http://localhost:5173/`. Vite needs Node 20.19 or newer (check with `node -v`).',
}

export const GUIDE_CAMPJ = {
  // ─────────────── TypeScript ───────────────
  typescript: {
    term: 'TypeScript', stands: 'TypeScript: JavaScript plus a type system',
    short: 'JavaScript plus types, checked before the code runs.',
    what: 'TypeScript is JavaScript with one big addition: **types**. You label what kind of value each variable, parameter and return value should hold (`number`, `string`, an object with certain properties…), and a checker called **tsc** (the TypeScript compiler) reads your code and reports every place where the labels don\'t match, **before anything runs**.\n\nNearly all JavaScript runs as TypeScript too, but the checker may flag it (an unlabelled parameter is an error in strict mode, for example). TypeScript just adds the labels.',
    how: 'A type label doesn\'t change what your code does. It lets the checker catch a wrong value before the code runs.\n\n**Two separate jobs:**\n1. **Checking.** `tsc` (or your editor, which runs the same checker in the background) reads every file, follows each value, and prints errors like `error TS2345: Argument of type \'string\' is not assignable to parameter of type \'number\'.`\n2. **Running.** Browsers and Node run JavaScript, so the types are **removed** first ("stripped" or "compiled away"). `const x: number = 5` becomes `const x = 5`. Nothing about types exists at run time.\n\n**The big consequence:** types catch mistakes *in your code*. They do not check data that arrives while the program runs (a form, a file, an API reply). A reply typed as a number can still turn out to be text.\n\n**Inference:** you don\'t label everything. `let height = 8400` is automatically a `number`; TypeScript works it out. You mostly annotate function parameters and the shapes of your data.\n\n**Strict mode:** `"strict": true` in `tsconfig.json` (the project\'s TypeScript settings file) turns on the most useful checks, like "this might be null." New projects should keep it on.\n\n**⛑️ In this game:** your TypeScript runs with the types stripped, the way many real build tools do it. **Nothing checks the types here**, so a wrong type just runs like plain JavaScript. Every type error in this camp is real `tsc` output, shown to you in cards and quizzes. On a real computer, your editor and `tsc` do the checking.',
    usage: [
      { code: '// altitude.ts\nfunction addAltitude(current: number, gain: number): number {\n  return current + gain\n}\nconsole.log(addAltitude(7950, 450))', out: '8400', note: 'Labels on the parameters and the return value. Correct code runs exactly like JavaScript.' },
      { code: 'addAltitude("7950", 450)', out: 'altitude.ts(6,13): error TS2345: Argument of type \'string\' is not assignable to parameter of type \'number\'.', note: 'Real `npx tsc --noEmit --strict` output. Plain JavaScript would have happily printed 7950450.' },
      { code: '$ npm install --save-dev typescript\n$ npx tsc --noEmit', out: '(no output when there are no errors)', note: 'Real computer: install it in the project, then check every file. `--noEmit` means "check only, don\'t write .js files."' },
      { code: '$ npx tsc -v', out: 'Version 7.0.2', note: 'Which version the project has (yours may differ).' },
    ],
    uses: ['Most professional front-end and Node projects: React apps, servers, libraries.', 'Large codebases where many people change code: the checker catches "you changed this function, and these 14 callers are now wrong."', 'Editor help: autocomplete that knows every property, "go to definition", and safe renaming across files.', 'Published npm packages ship type definitions, so your editor knows how to call them.'],
    when: ['Any project that will grow beyond a few files or live longer than a weekend.', 'Code other people will use or change, including you in six months.', 'When you want your editor to catch typos and wrong arguments as you type.'],
    whenNot: ['As a replacement for checking real-world data. Types vanish before running, so validate input from users, files and APIs at run time.', 'For a ten-line throwaway script, where setting up a build step costs more than it saves.', 'As a reason to skip tests. Types catch "wrong kind of value"; they can\'t catch "right kind, wrong answer" like `return a - b` in an add function.'],
    mistakes: [
      { wrong: 'npx tsc   (TypeScript not installed in the project)', result: 'This is not the tsc command you are looking for', why: 'npx downloaded an unrelated old package that happens to be called "tsc". Install the real one first: `npm install --save-dev typescript`, then `npx tsc`.' },
      { prose: 'Seeing the code "work" in this game (or in a tool that only strips types) and concluding the types are right.', why: 'Stripping is not checking. Only `tsc` or your editor checks. Many build tools (including the dev servers you\'ll use with React) strip types without checking them, so run `npx tsc --noEmit` before you ship.' },
      { prose: 'Sprinkling `any` everywhere to make the red squiggles go away.', why: '`any` switches checking off for that value, so you\'re back to plain JavaScript with extra typing. Fix the type, or use `unknown` and check the value.' },
    ],
    tips: ['Turn on `"strict": true` from day one. Adding it to an old project later means fixing hundreds of errors at once.', 'Hover over any variable in your editor to see the type TypeScript worked out for it.', 'Run `npx tsc --noEmit` as a script (`"typecheck"` in package.json) so you can check the whole project with one command.'],
    related: ['type-annotation', 'type-errors', 'interface-type', 'union-type'],
    os: TS_OS,
  },
  'type-annotation': {
    term: 'Type annotation', short: 'A `: type` label after a name, saying what kind of value belongs there.',
    what: 'A type annotation is the `: something` you write after a variable, parameter or function\'s brackets: `let camp: string`, `(gain: number)`, `): boolean {`. It tells TypeScript "only this kind of value belongs here," so the checker can complain when something else shows up.',
    how: '**Where annotations go:**\n• variables: `let camp: string = "Camp IV"`\n• parameters: `function toFeet(metres: number)`\n• return values, after the brackets: `function toFeet(metres: number): number`\n\n**The basic types:** `string`, `number` (all numbers, whole or decimal), `boolean` (`true`/`false`), `null`, `undefined`.\n**Arrays:** `string[]` (an array of strings) or `number[]`.\n**Objects:** describe their shape (see the interface card).\n**Functions with no result:** return type `void`.\n\n**Inference does most of the work.** `let height = 8400` is already a `number`, so `height = "high"` is an error even without a label. Annotate where TypeScript can\'t guess: **function parameters** (they\'re `any` otherwise, which strict mode rejects) and the shapes of your data.\n\n**Annotations are erased** before running. `const x: number = 5` becomes `const x = 5`. They cost nothing at run time and check nothing at run time.',
    usage: [
      { code: 'let camp: string = "Camp IV"\ncamp = 4', out: 'b.ts(2,1): error TS2322: Type \'number\' is not assignable to type \'string\'.', note: 'The label says string, so a number is rejected (real tsc output).' },
      { code: 'function toFeet(metres: number): number {\n  return Math.round(metres * 3.28084)\n}\nconsole.log(toFeet(8849))', out: '29032', note: 'Parameter and return type annotated.' },
      { code: 'const gear: string[] = ["rope", "axe"]\ngear.push(5)', out: 'error TS2345: Argument of type \'number\' is not assignable to parameter of type \'string\'.', note: 'An array of strings only takes strings.' },
      { code: 'let y = 5\ny = "five"', out: 'error TS2322: Type \'string\' is not assignable to type \'number\'.', note: 'No annotation, but TypeScript inferred number from the 5.' },
    ],
    uses: ['Documenting what a function expects, right where it\'s defined.', 'Catching wrong arguments at every call site the moment you save.', 'Making autocomplete accurate: after `metres: number`, typing `metres.` lists number methods like `toFixed`.'],
    when: ['On every function parameter.', 'On return types of functions other code depends on (it stops you accidentally changing what they return).', 'On variables that start empty and get filled later: `let names: string[] = []`.'],
    whenNot: ['On every single variable. `const total: number = 5 + 3` adds noise; TypeScript already knows. Let inference handle the obvious.', 'As a claim about outside data. `const reply: Forecast = await res.json()` doesn\'t check anything; it just trusts the server.'],
    mistakes: [
      { wrong: 'function greet(name) { return "Hi " + name }', result: 'e.ts(1,16): error TS7006: Parameter \'name\' implicitly has an \'any\' type.', why: 'In strict mode every parameter needs a type. Write `greet(name: string)`.' },
      { wrong: 'function total(n: number): number {\n  if (n > 0) return n\n}', result: 'error TS2366: Function lacks ending return statement and return type does not include \'undefined\'.', why: 'When n is 0 or less, nothing is returned. Return something on every path.' },
      { wrong: 'let count: Number = 0', result: '(works, but it\'s the wrong type)', why: 'Lowercase `number`, `string`, `boolean` are the real types. The capitalised versions are wrapper objects you almost never want.' },
    ],
    tips: ['Read `x: number` aloud as "x, which is a number." It makes code reviews easier.', 'If you\'re not sure what type to write, leave it off, hover in your editor to see what TypeScript inferred, then decide.'],
    related: ['typescript', 'type-errors', 'interface-type'],
  },
  'interface-type': {
    term: 'Interfaces and type aliases', short: 'A named description of an object\'s shape: which properties, and what type each one is.',
    what: 'An **interface** describes the shape of an object: the property names it must have and the type of each. Once named, you use it like any other type: `function brief(c: Climber)`. A **type alias** (`type Name = …`) gives a name to *any* type, including object shapes, unions and more.',
    how: '```\ninterface Climber {\n  name: string\n  altitude: number\n  oxygen?: boolean\n}\n```\n• each line is `property: type`\n• `?` makes a property **optional**: it may be missing, so its type is really `boolean | undefined`\n• an object of this type must have every required property, with the right types\n• when you write an object literal directly, **extra** properties are flagged too, because they\'re usually typos\n\n**`type` does the same for objects:**\n`type Climber = { name: string; altitude: number }`\nFor plain object shapes either works. `type` can also name unions (`type Weather = "clear" | "storm"`), which an interface can\'t. Many teams pick one style for objects and stick to it.\n\n**Arrays of shapes:** `Climber[]`.\n**Shapes inside shapes:** a property can be another interface: `leader: Climber`.\n\nLike all types, interfaces disappear before running. They describe; they don\'t check live data.',
    usage: [
      { code: 'interface Climber {\n  name: string\n  altitude: number\n  oxygen?: boolean\n}\nconst ana: Climber = { name: "Ana", altitude: 7950 }\nconsole.log(ana.name)', out: 'Ana', note: '`oxygen` is optional, so leaving it out is fine.' },
      { code: 'const ana: Climber = { name: "Ana" }', out: 'c.ts(6,7): error TS2741: Property \'altitude\' is missing in type \'{ name: string; }\' but required in type \'Climber\'.', note: 'A required property is missing (real tsc output).' },
      { code: 'console.log(ana.nme)', out: 'c.ts(8,17): error TS2551: Property \'nme\' does not exist on type \'Climber\'. Did you mean \'name\'?', note: 'Typos in property names are caught, with a suggestion.' },
      { code: 'type Tent = { name: string; capacity: number }\nconst tents: Tent[] = [\n  { name: "North", capacity: 3 },\n  { name: "South", capacity: 2 },\n]\nconsole.log(tents.length)', out: '2', note: 'A type alias for an object, and an array of them.' },
    ],
    uses: ['Describing the data your app passes around: users, orders, gear items, API replies.', 'Typing React component props (you\'ll do this soon).', 'Sharing one definition across many files, so a change to the shape shows every place that needs updating.'],
    when: ['Any object shape you use in more than one place.', 'Function parameters that take objects.', 'Describing what you *expect* an API to return (then still check it at run time).'],
    whenNot: ['For one-off tiny objects used in a single line, where inference already knows the shape.', 'As validation. `res.json() as Climber` makes TypeScript trust you; if the server sends `{ nam: "Ana" }`, nothing stops it. Check real data with code.'],
    mistakes: [
      { wrong: 'const ben: Climber = { name: "Ben", altitude: 7900, team: "red" }', result: 'error TS2353: Object literal may only specify known properties, and \'team\' does not exist in type \'Climber\'.', why: 'Extra properties in a literal are flagged because they\'re usually typos. Add `team` to the interface if it belongs there.' },
      { wrong: 'function o2(c: Climber) { return c.oxygen.toFixed(1) }   (oxygen?: number)', result: 'error TS18048: \'c.oxygen\' is possibly \'undefined\'.', why: 'Optional means it might be missing. Check first: `if (c.oxygen !== undefined)`, or give a default: `(c.oxygen ?? 0).toFixed(1)`.' },
      { prose: 'Putting commas between interface lines like an object, or `=` signs.', why: 'Interface lines use `name: type`, separated by new lines or semicolons. `name = string` is a syntax error.' },
    ],
    tips: ['Name interfaces with a capital letter and a noun: `Climber`, `GearItem`, `Forecast`.', 'Hover over an object in your editor to see which interface it matched, and which property is wrong.'],
    related: ['type-annotation', 'union-type', 'typescript', 'object'],
  },
  'union-type': {
    term: 'Union types', short: '"This OR that": a value that may be one of several types or exact values, written with `|`.',
    what: 'A union type says a value can be one of several options, separated by `|` (read it as "or"). `number | string` means "a number or a string". Unions of exact values are even more useful: `"clear" | "windy" | "storm"` means only those three strings are allowed, nothing else.',
    how: '**Unions of exact values (literal types):**\n`type Weather = "clear" | "windy" | "storm"`\nNow `let today: Weather = "sunny"` is an error. Any other string is an error.\n\n**Unions of types:** `id: number | string`. Inside the function you can only use what *every* option supports. To use string-only things, **narrow** first:\n```\nif (typeof id === "string") {\n  // here TypeScript knows id is a string\n  return id.toUpperCase()\n}\n// here it knows id is a number\nreturn id.toFixed(0)\n```\nChecks TypeScript understands for narrowing: `typeof x === "string"`, `x === "storm"`, `x !== undefined`, `Array.isArray(x)`, and `"prop" in x`.\n\n**Optional values are unions too:** `oxygen?: number` is `number | undefined`, and `document.querySelector(...)` returns `Element | null`. Strict mode makes you handle the `null`.\n\n**Exhaustiveness:** if a function promises to return a string for every `Weather`, and your `switch` forgets `"storm"`, tsc reports that the function might not return.',
    usage: [
      { code: 'type Weather = "clear" | "windy" | "storm"\nlet today: Weather = "sunny"', out: 'd.ts(2,5): error TS2322: Type \'"sunny"\' is not assignable to type \'Weather\'.', note: 'Only the listed values are allowed (real tsc output).' },
      { code: 'function label(id: number | string): string {\n  if (typeof id === "string") return id.toUpperCase()\n  return `T-${id}`\n}\nconsole.log(label("north"))\nconsole.log(label(7))', out: 'NORTH\nT-7', note: 'Narrowing with typeof, then each branch uses the right methods.' },
      { code: 'function describe(id: number | string) {\n  return id.toUpperCase()\n}', out: 'error TS2339: Property \'toUpperCase\' does not exist on type \'string | number\'.\n  Property \'toUpperCase\' does not exist on type \'number\'.', note: 'Not narrowed: numbers have no toUpperCase.' },
      { code: 'const el = document.querySelector("#count")\nel.textContent = "3"', out: 'error TS18047: \'el\' is possibly \'null\'.', note: 'querySelector returns Element | null. Check `if (el)` first.' },
    ],
    uses: ['Fixed sets of options: statuses (`"open" | "full"`), sizes, roles, weather, HTTP methods.', 'Values that may be missing (`string | undefined`, `Element | null`): the checker forces you to handle the missing case.', 'Functions that accept a couple of input forms, like an id as a number or a string.'],
    when: ['A value can only ever be one of a few known options. Prefer `"open" | "full"` over a plain `string`.', 'Something might be null or undefined and you want to be forced to handle it.'],
    whenNot: ['As a dumping ground: `string | number | boolean | object` tells you almost nothing. If every function has to narrow it, the design needs rethinking.', 'Expecting it to block bad live data. A union of three strings is erased before running; text from a form can still be "sunny".'],
    mistakes: [
      { wrong: 'type Weather = "clear" | "windy" | "storm"\nfunction advice(w: Weather): string {\n  switch (w) {\n    case "clear": return "Climb"\n    case "windy": return "Wait"\n  }\n}', result: 'error TS2366: Function lacks ending return statement and return type does not include \'undefined\'.', why: '"storm" isn\'t handled, so the function can end without returning. Add the missing case. The checker caught the forgotten case.' },
      { wrong: 'type Weather = "clear" | "Windy"', result: '(then "windy" is rejected everywhere)', why: 'Literal types are exact, including capital letters.' },
      { prose: 'Using `x!` (the non-null assertion) everywhere to silence "possibly null".', why: 'The `!` tells TypeScript "trust me, it\'s there." If you\'re wrong, it crashes at run time anyway. Check with `if` instead.' },
    ],
    tips: ['Name your unions (`type Status = "open" | "full"`) so the options live in one place.', 'In your editor, type a variable of a literal union then a quote mark: autocomplete lists exactly the allowed values.'],
    related: ['type-annotation', 'interface-type', 'type-errors', 'if-else'],
  },
  'type-errors': {
    term: 'Type errors (reading tsc output)', short: 'tsc\'s report of a mismatch: file, line, column, an error code, and a sentence saying what didn\'t fit.',
    what: 'A **type error** is TypeScript telling you that a value doesn\'t match the type something expects. It\'s found by **reading** your code, not running it, so you see it before any user does. Unlike a JavaScript runtime error, a type error doesn\'t stop anything by itself: it\'s a warning from the checker that the code is wrong.',
    how: '**Reading one, piece by piece:**\n`altitude.ts(6,13): error TS2345: Argument of type \'string\' is not assignable to parameter of type \'number\'.`\n• `altitude.ts` the file\n• `(6,13)` line 6, column 13\n• `TS2345` the error code (search it to find explanations)\n• the sentence: "you gave X where Y was expected"\n\n**"Is not assignable to"** is the phrase you\'ll see most. Read it as "doesn\'t fit into." `Type \'number\' is not assignable to type \'string\'` = "you put a number where a string goes."\n\n**The common ones (all real tsc output):**\n• `TS2322` Type \'X\' is not assignable to type \'Y\': a wrong value in a variable or property\n• `TS2345` Argument of type … is not assignable to parameter of type …: a wrong argument to a function\n• `TS2339` / `TS2551` Property \'x\' does not exist on type …: a typo, or a property that type doesn\'t have\n• `TS2741` Property \'x\' is missing in type …: a required property left out\n• `TS18047` / `TS18048` \'x\' is possibly \'null\' / \'undefined\': handle the missing case first\n• `TS7006` Parameter \'x\' implicitly has an \'any\' type: add a type to the parameter\n\n**Pretty or plain:** in a terminal, tsc may print the same facts as `altitude.ts:6:13 - error TS2345: …` with the bad code underlined. File, line, column, code and sentence are all still there.\n\n**Where you see them:** red squiggles in your editor as you type, and a list when you run `npx tsc --noEmit`. When there are no errors, tsc prints nothing.\n\n**Fix the first error first.** One mistake can cause several errors further down.\n\n**⛑️ In this game** nothing type-checks your code, so you won\'t see these when you press Run. That\'s why this camp shows you the real messages to read.',
    usage: [
      { code: '$ npx tsc --noEmit', out: 'src/gear.ts(12,5): error TS2322: Type \'string\' is not assignable to type \'number\'.\nsrc/gear.ts(20,18): error TS2551: Property \'weigth\' does not exist on type \'GearItem\'. Did you mean \'weight\'?', note: 'Real computer: one line per error. Go to each file and line.' },
      { code: '$ npx tsc --noEmit\n$ echo $?', out: '0', note: 'No output and exit code 0: no type errors.' },
      { code: 'const el = document.querySelector("#count")\nif (el) {\n  el.textContent = "3"\n}', note: 'The fix for TS18047 ("possibly null"): check before use. Inside the if, el is known to exist.' },
    ],
    uses: ['Catching wrong arguments, typos and missing cases while you type, instead of when a user hits them.', 'Refactoring safely: rename a property, and the error list is your to-do list of every place to update.', 'Running `tsc --noEmit` automatically before code is merged, so type errors can\'t reach the live site.'],
    when: ['Read every one before running or shipping. They\'re free bug reports.', 'After changing a type or function signature: the new errors show exactly what depends on it.'],
    whenNot: ['Don\'t silence them with `any`, `as`, `!` or `// @ts-ignore` just to make them disappear. Each one hides a possible crash.', 'Don\'t assume no type errors means no bugs. Types can\'t see logic mistakes (`a - b` instead of `a + b`) or bad live data. That\'s what tests and run-time checks are for.'],
    mistakes: [
      { prose: 'Reading only the error code and guessing.', why: 'The sentence after the code says exactly what\'s wrong: which type you gave, and which was expected. Read it slowly, left to right.' },
      { prose: 'Starting at the last error in a long list.', why: 'Later errors are often caused by earlier ones. Fix the first, re-run, repeat.' },
      { wrong: 'const n = Number(input) as string', result: 'error TS2352: Conversion of type \'number\' to type \'string\' may be a mistake…', why: '`as` doesn\'t convert anything; it only changes what TypeScript believes. To turn a number into text, use `String(n)`.' },
    ],
    tips: ['Copy the error code (like TS2345) into a search engine when the sentence still doesn\'t make sense.', 'Add `"typecheck": "tsc --noEmit"` to your package.json scripts and run `npm run typecheck` before every commit.'],
    related: ['typescript', 'type-annotation', 'union-type', 'error-types'],
  },

  // ─────────────── React ───────────────
  react: {
    term: 'React', short: 'A JavaScript library for building user interfaces out of components. You describe the screen; React updates the DOM.',
    what: 'React is a free, open-source JavaScript library for building user interfaces. Instead of finding elements and changing them by hand (`querySelector`, `textContent`, `updateCount()` everywhere), you write **components**: functions that return a description of what the screen should look like for the current data. When the data changes, React works out what\'s different and updates the real DOM for you.',
    how: 'In Camp III you built a packing checklist by hand: every click had to update the button, the class, the aria attribute AND the count, and forgetting one left the page out of sync. React flips that around:\n\n**1. You describe, React does.** A component says "for this data, the screen looks like this." It\'s *declarative*: what, not how.\n**2. Data changes → React re-renders.** You call a state setter (like `setPacked(1)`), React calls your component function again, gets the new description, compares it with the last one, and changes **only** the DOM parts that differ.\n**3. Everything is components.** Small ones (a gear item) combine into bigger ones (a list), into a whole app.\n\n**Pieces you\'ll learn:** JSX (the HTML-like syntax), components, props (inputs), state (memory), events, lists with keys, and effects.\n\n**React is a library, not a whole framework.** It handles the view. Projects add tools around it: **Vite** (a fast dev server and build tool) for single-page apps, or frameworks built on React (like Next.js) when you also want routing and server rendering.\n\n**Hooks** are React functions whose names start with `use` (`useState`, `useEffect`). They must be called at the top level of a component, never inside ifs or loops, so React can match them up on every render.\n\n**⛑️ In this game** the React preview compiles your JSX, renders `App`, and gives you `useState` and `useEffect` ready to use (an `import … from \'react\'` line works too). The checks click your buttons and read the page.',
    usage: [
      { code: 'import { useState } from "react"\n\nfunction App() {\n  const [packed, setPacked] = useState(0)\n  return (\n    <button onClick={() => setPacked(packed + 1)}>\n      Packed: {packed}\n    </button>\n  )\n}', out: '(a button reading "Packed: 0"; each tap adds 1)', note: 'No querySelector, no textContent. Change the state and React updates the text.' },
      { code: '$ npm create vite@latest gear-app -- --template react-ts\n$ cd gear-app\n$ npm install\n$ npm run dev', out: '  VITE v8.3.4  ready in 312 ms\n\n  ➜  Local:   http://localhost:5173/', note: 'Real computer: a new React + TypeScript project with a dev server that reloads as you save (version numbers vary).' },
      { code: '// src/main.tsx (made for you by the template)\nimport { StrictMode } from \'react\'\nimport { createRoot } from \'react-dom/client\'\nimport \'./index.css\'\nimport App from \'./App.tsx\'\n\ncreateRoot(document.getElementById(\'root\')!).render(\n  <StrictMode>\n    <App />\n  </StrictMode>,\n)', note: 'How React attaches to a real page: find the `#root` div, render `<App />` into it. StrictMode adds extra development-only checks.' },
    ],
    uses: ['Interactive web apps: dashboards, shops, editors, chat, social feeds.', 'Anything where lots of the screen depends on changing data.', 'Mobile apps too, through React Native, which uses the same component ideas.'],
    when: ['The page has a lot of state that changes as people use it, and keeping the DOM in sync by hand is getting messy.', 'You want reusable pieces (the same card or button in many places).', 'A team is building and maintaining the interface for a long time.'],
    whenNot: ['A mostly static page (a blog post, a landing page, a menu). Plain HTML and CSS is faster, simpler and works without JavaScript.', 'Before you understand the DOM, events and functions. React is built on them; skipping them makes React errors baffling.', 'A tiny widget on an existing page. A few lines of plain JavaScript can beat adding a whole library.'],
    mistakes: [
      { prose: 'Mixing React and manual DOM changes (`document.querySelector(...).textContent = ...`) on the same elements.', why: 'React owns the DOM it renders. On its next render it overwrites your change, or gets confused. Change state instead and let React update the page.' },
      { wrong: 'if (ready) { const [n, setN] = useState(0) }', result: 'React Hook "useState" is called conditionally. React Hooks must be called in the exact same order in every component render.', why: 'That\'s the official lint rule\'s message (eslint-plugin-react-hooks). Hooks go at the top of the component, every render, in the same order.' },
      { prose: 'Seeing `console.log` inside an effect print twice while developing.', why: 'Not a bug in your code: StrictMode (in development only) mounts, unmounts and re-mounts components to help you catch effects that don\'t clean up. Production runs them once.' },
    ],
    tips: ['Install the React Developer Tools browser extension: it shows your component tree, props and state live.', 'Think "what should the screen look like for this data?", not "what should I change when they click?"', 'Keep components small. If a component scrolls off the screen, split it.'],
    related: ['component', 'jsx', 'props', 'state', 'dom'],
    os: VITE_OS,
  },
  component: {
    term: 'Component', short: 'A function whose name starts with a capital letter and returns JSX: one reusable piece of the screen.',
    what: 'A React **component** is a JavaScript function that returns JSX: a description of a piece of the screen. You use it like an HTML tag: `<GearItem />`. Components are the building blocks: a `Header`, a `GearItem`, a `GearList` made of `GearItem`s, and an `App` that holds it all.',
    how: 'Write a component once, then use it as many times as you need, each with its own props.\n\n**Rules:**\n• the name **must start with a capital letter**: `GearItem`, not `gearItem`. Lowercase names are treated as HTML tags\n• it **returns JSX** (or `null` to show nothing)\n• it returns **one** root element. Wrap siblings in a `<div>` or a **fragment** `<>…</>` (an invisible wrapper)\n• it should be **pure while rendering**: same props and state in, same JSX out, with no side effects during the render itself (no changing outside variables, no fetching). Side effects belong in event handlers or effects\n\n**Using one:** `<Header />` (self-closing) or `<Card>…</Card>` with content inside.\n\n**Composition:** components render other components. `App` renders `GearList`, which renders many `GearItem`s. Data flows down through **props**.\n\n**Exporting:** in real projects each component often lives in its own file: `export default function GearItem() { … }` and `import GearItem from "./GearItem"`. In the game everything sits in one editor, and React looks for `function App()`.',
    usage: [
      { code: 'function Header() {\n  return <h1>The Balcony</h1>\n}\n\nfunction App() {\n  return (\n    <>\n      <Header />\n      <p>8,400 m</p>\n    </>\n  )\n}', out: '<h1>The Balcony</h1>\n<p>8,400 m</p>', note: 'Two components. The fragment `<>…</>` groups siblings without adding an element.' },
      { code: 'function Tent() {\n  return <li className="tent">⛺</li>\n}\nfunction App() {\n  return <ul><Tent /><Tent /><Tent /></ul>\n}', out: '(a list of three tents)', note: 'Write once, use many times.' },
      { code: 'function Warning({ show }) {\n  if (!show) return null\n  return <p className="alert">Storm coming</p>\n}', note: 'Returning null renders nothing.' },
    ],
    uses: ['Every repeated piece of an interface: cards, rows, buttons, menus, avatars.', 'Splitting a big page into readable, testable parts.', 'Sharing pieces across projects (component libraries).'],
    when: ['Something appears more than once.', 'A chunk of JSX has its own clear job, or a component is getting too long to read.'],
    whenNot: ['Don\'t split everything into one-line components; a component should earn its name.', 'Don\'t define a component inside another component\'s function. It gets re-created on every render, so its state resets every time. Define components at the top level.'],
    mistakes: [
      { wrong: 'function forecast() { … }\n… <forecast />', result: 'The tag <forecast> is unrecognized in this browser. If you meant to render a React component, start its name with an uppercase letter.', why: 'Lowercase tags are treated as HTML elements, and there\'s no HTML `<forecast>`. Rename it `Forecast`.' },
      { wrong: 'function App() {\n  return <h1>Camp</h1><p>Ready</p>\n}', result: 'error TS2657: JSX expressions must have one parent element.', why: 'A component returns one root. Wrap them: `<><h1>Camp</h1><p>Ready</p></>`. (In this game the same mistake shows a confusing `SyntaxError: Unterminated regular expression` instead.)' },
      { prose: 'Forgetting `return`, or writing `return` with the JSX starting on the next line without brackets.', why: 'JavaScript inserts a semicolon after a bare `return`, so the component returns undefined. Use `return (` and put the JSX inside the brackets.' },
    ],
    tips: ['One component per job: if you can\'t name it in two words, it\'s probably doing too much.', 'Wrap multi-line JSX in `return ( … )`, always.'],
    related: ['jsx', 'props', 'react', 'function'],
  },
  jsx: {
    term: 'JSX', stands: 'JavaScript XML (HTML-like tags written inside JavaScript)',
    short: 'HTML-like syntax inside JavaScript that describes what a component shows. Curly braces drop in JavaScript values.',
    what: 'JSX lets you write tags that look like HTML right inside your JavaScript: `return <h1>Camp {n}</h1>`. It isn\'t HTML and it isn\'t a string: a build step turns each tag into a plain function call (`jsx("h1", …)`) that creates a description React uses to build the DOM.',
    how: '**Curly braces `{ }` = "JavaScript here".** Inside them, put any **expression** (something that produces a value):\n• `{altitude}` a variable\n• `{altitude * 3.28}` maths\n• `{name.toUpperCase()}` a method call\n• `{ok ? "Go" : "Wait"}` a choice (the ternary)\n• `{ready && <p>Ready!</p>}` show something only when true\nStatements like `if` and `for` don\'t fit inside braces. Use a ternary or `&&`, or prepare the value above the `return`.\n\n**Differences from HTML:**\n• `className` instead of `class` (class is a JavaScript keyword)\n• `htmlFor` instead of `for` on labels\n• every tag must close: `<img />`, `<input />`, `<br />`\n• event and attribute names are camelCase: `onClick`, `tabIndex`\n• `style` takes an object: `style={{ color: "red" }}` (outer braces = JavaScript, inner = the object)\n• attribute values: strings in quotes (`id="count"`), anything else in braces (`kg={4}`)\n• comments: `{/* like this */}`\n\n**What renders:** strings and numbers show as text; `null`, `undefined`, `true` and `false` show nothing; arrays render each item. A plain object can\'t be shown.\n\n**Safe by default:** text you put in braces is escaped, so `{userInput}` containing `<script>` shows as text, like `textContent` did.\n\n**Files:** `.jsx` (JavaScript) or `.tsx` (TypeScript).',
    usage: [
      { code: 'const altitude = 8400\nconst ok = altitude < 8500\nreturn (\n  <div className="card">\n    <p>Altitude: {altitude} m</p>\n    <p>{ok ? "Go" : "Turn back"}</p>\n  </div>\n)', out: 'Altitude: 8400 m\nGo', note: 'Variables and a ternary in braces, `className` for the class.' },
      { code: '<label htmlFor="name">Name</label>\n<input id="name" />\n<img src="tent.png" alt="Orange tent" />', note: 'htmlFor, and every tag closed.' },
      { code: '{storm && <p className="alert">Storm warning</p>}', out: '(the paragraph appears only while storm is true)', note: 'Conditional rendering with &&.' },
      { code: '<p style={{ color: "crimson", fontSize: 18 }}>Death zone</p>', note: 'Style is an object with camelCase names; numbers mean px.' },
    ],
    uses: ['Writing every React component\'s output.', 'Mixing data into markup safely, without building HTML strings.'],
    when: ['Any time you write a React component.'],
    whenNot: ['Outside a project with a build step that understands it: a browser can\'t run JSX directly from a plain `<script>`.', 'For heavy logic. Do the work above the `return` and keep the JSX readable.'],
    mistakes: [
      { wrong: '<div class="card">', result: 'Invalid DOM property `class`. Did you mean `className`?', why: 'React\'s development warning in the console. Use `className`.' },
      { wrong: '<img src="tent.png">', result: 'error TS17008: JSX element \'img\' has no corresponding closing tag.', why: 'Every JSX tag must close: `<img src="tent.png" />`. (This game shows `SyntaxError: Unterminated JSX contents` for the same mistake.)' },
      { wrong: '<p>{climber}</p>   (climber is an object)', result: 'Objects are not valid as a React child (found: object with keys {name, altitude}). If you meant to render a collection of children, use an array instead.', why: 'React can\'t show a whole object. Show a property: `{climber.name}`.' },
      { wrong: '<p>{if (ok) "Go"}</p>', result: 'SyntaxError (an `if` is a statement, not an expression)', why: 'Use a ternary inside braces: `{ok ? "Go" : "Wait"}`.' },
      { wrong: '{count && <p>{count} items</p>}   (count is 0)', result: '0', why: '`0 && …` evaluates to 0, and React renders numbers. Use `{count > 0 && …}`.' },
    ],
    tips: ['Two braces in `style={{ }}` aren\'t special syntax: one for "JavaScript here", one for the object.', 'When JSX gets hard to read, move logic into a variable above the `return`.'],
    related: ['component', 'react', 'html-element', 'template-literal'],
  },
  props: {
    term: 'Props', stands: 'properties (inputs passed into a component)',
    short: 'The inputs a parent passes to a component, written like HTML attributes. Read-only inside the component.',
    what: '**Props** are how you pass data into a component, the same way arguments go into a function. `<GearItem name="Rope" kg={4} />` passes two props. Inside, the component receives them as one object: `function GearItem(props)` or, more often, unpacked: `function GearItem({ name, kg })`.',
    how: '**Passing:**\n• strings in quotes: `name="Rope"`\n• anything else in braces: `kg={4}`, `packed={true}`, `item={gearObject}`, `onToggle={handleToggle}` (yes, functions too)\n• just the name means true: `<GearItem packed />` is `packed={true}`\n\n**Receiving:** React calls your component with **one object** holding every prop. Destructuring `({ name, kg })` pulls out the ones you need. You can give defaults: `({ kg = 0 })`.\n\n**`children`:** whatever you put between a component\'s tags arrives as the special prop `children`:\n`<Card>Hello</Card>` → `function Card({ children })`.\n\n**Read-only.** A component must never change its props. They belong to the parent. To change what\'s shown, the **parent** changes its state and passes new props. Data flows **down**; requests to change flow **up** by calling a function prop (like `onToggle(id)`).\n\n**Typing props in TypeScript:**\n```\ninterface GearProps {\n  name: string\n  kg: number\n}\nfunction GearItem({ name, kg }: GearProps) { … }\n```\nNow `<GearItem name="Rope" />` is a type error: `kg` is missing.',
    usage: [
      { code: 'function GearItem({ name, kg }) {\n  return <li>{name}: {kg} kg</li>\n}\n\nfunction App() {\n  return (\n    <ul>\n      <GearItem name="Rope" kg={4} />\n      <GearItem name="Stove" kg={1} />\n    </ul>\n  )\n}', out: 'Rope: 4 kg\nStove: 1 kg', note: 'One component, two different sets of props.' },
      { code: 'function Card({ title, children }) {\n  return <section><h2>{title}</h2>{children}</section>\n}\n<Card title="Weather"><p>Wind 30 km/h</p></Card>', out: 'Weather\nWind 30 km/h', note: 'Content between the tags arrives as children.' },
      { code: '<GearItem name="Rope" />   (TypeScript, kg: number required)', out: 'error TS2741: Property \'kg\' is missing in type \'{ name: string; }\' but required in type \'GearProps\'.', note: 'Real tsc output for a missing prop.' },
    ],
    uses: ['Reusing one component with different data (every row in a list).', 'Passing event handlers down so a child can tell its parent "I was clicked".', 'Configuring components: sizes, labels, colours, disabled states.'],
    when: ['A component needs data it doesn\'t own.', 'A child needs to trigger a change in its parent: pass a function prop like `onToggle`.'],
    whenNot: ['Don\'t change props inside the component (`props.kg = 5`). Ask the parent to change its state instead.', 'Don\'t copy a prop into state "just because" (`useState(props.name)`): the state won\'t update when the prop changes. Use the prop directly.', 'Don\'t pass props through five layers of components that don\'t use them. That\'s a sign to restructure (React has a feature called context for this).'],
    mistakes: [
      { wrong: '<GearItem kg="4" />', result: '(kg is the string "4", so kg + 1 gives "41")', why: 'Quotes always mean a string. Numbers, booleans, objects and functions go in braces: `kg={4}`.' },
      { wrong: 'function GearItem(name, kg) { … }', result: '(name is the whole props object, kg is undefined)', why: 'React passes ONE object. Destructure it: `function GearItem({ name, kg })`.' },
      { wrong: 'onToggle={toggle(item.id)}', result: '(toggle runs during render, not on click; if it sets state you get "Too many re-renders")', why: 'Pass a function: `onToggle={() => toggle(item.id)}`.' },
    ],
    tips: ['Name event props `onSomething` (`onToggle`, `onAdd`) and the functions that handle them `handleSomething`.', 'In TypeScript, typing props gives autocomplete for every prop when you use the component.'],
    related: ['component', 'state', 'react-events', 'parameter'],
  },
  state: {
    term: 'State (useState)', short: 'A component\'s memory. Changing it with its setter makes React re-render with the new value.',
    what: '**State** is data a component remembers between renders and that can change over time: a count, the text in a box, whether a menu is open, the list of gear. You create it with the `useState` hook, which gives you the current value and a **setter** function. Calling the setter tells React "this changed, draw the screen again."',
    how: '`const [packed, setPacked] = useState(0)`\n• `useState(0)`: create state, starting at 0 (only used on the first render)\n• `packed`: the current value **for this render**\n• `setPacked`: the function that changes it\n• the `[a, b] =` part is array destructuring: useState returns a pair\n\n**What happens when you call `setPacked(1)`:**\n1. React stores the new value\n2. React calls your component function again (a **re-render**)\n3. This time `useState` returns 1\n4. React compares the new JSX with the old and updates only what changed in the DOM\n\n**Why not a normal variable?** `let packed = 0; packed++` changes the variable, but React doesn\'t know, so nothing re-renders. And on the next render the line `let packed = 0` runs again and resets it.\n\n**Never change state directly. Replace it.**\n• numbers/strings: `setPacked(packed + 1)`\n• arrays: `setItems([...items, newItem])` (add), `setItems(items.filter(i => i.id !== id))` (remove), `setItems(items.map(i => i.id === id ? { ...i, packed: !i.packed } : i))` (update one)\n• objects: `setClimber({ ...climber, altitude: 8400 })`\n`items.push(x)` changes the same array, so React sees "same array" and may not re-render.\n\n**The value is a snapshot.** Within one click handler, `packed` doesn\'t change after you call the setter; you get the new value on the next render. If the new value depends on the old one, pass a function: `setPacked(p => p + 1)`.\n\n**Derived values aren\'t state.** "Packed: 2 of 5" can be computed from the items each render: `items.filter(i => i.packed).length`. Storing it separately invites it to go out of sync.',
    usage: [
      { code: 'function App() {\n  const [packed, setPacked] = useState(0)\n  return (\n    <>\n      <p>Packed: {packed}</p>\n      <button onClick={() => setPacked(packed + 1)}>Pack one</button>\n    </>\n  )\n}', out: 'Packed: 0 → tap → Packed: 1 → tap → Packed: 2', note: 'The classic counter.' },
      { code: 'const [items, setItems] = useState(["Rope"])\n// add without mutating:\nsetItems([...items, "Stove"])', out: '[ \'Rope\', \'Stove\' ]', note: 'A brand-new array, so React notices.' },
      { code: 'setPacked(packed + 1)\nsetPacked(packed + 1)\n// packed was 0: result is 1, not 2\n\nsetPacked(p => p + 1)\nsetPacked(p => p + 1)\n// result is 2', note: 'Updater functions use the latest value; the snapshot doesn\'t.' },
      { code: 'const [name, setName] = useState("Headlamp")\n<input value={name} onChange={e => setName(e.target.value)} />', note: 'A **controlled input**: state holds the text, every keystroke updates it.' },
    ],
    uses: ['Counters, toggles, open/closed menus, selected tabs.', 'Form inputs (controlled inputs).', 'Lists that grow and shrink: to-dos, carts, gear checklists.'],
    when: ['A value changes while the app runs AND the screen should show the change.'],
    whenNot: ['For values you can calculate from other state or props (totals, counts, filtered lists). Compute them during render.', 'For values that never change: use a normal `const`, outside the component if it\'s the same for everyone.', 'For data that doesn\'t affect the screen (like a timer id). React has `useRef` for that.'],
    mistakes: [
      { wrong: 'let count = 0\n<button onClick={() => count++}>{count}</button>', result: '(the button keeps showing 0)', why: 'React doesn\'t know a plain variable changed. Use `useState` and its setter.' },
      { wrong: '<button onClick={setCount(count + 1)}>', result: 'Too many re-renders. React limits the number of renders to prevent an infinite loop.', why: 'The setter is called during render, which causes a render, which calls it again… Pass a function: `onClick={() => setCount(count + 1)}`.' },
      { wrong: 'items.push("Stove")\nsetItems(items)', result: '(the new item doesn\'t appear)', why: 'Same array object, so React skips the update. Make a new array: `setItems([...items, "Stove"])`.' },
      { wrong: 'setCount(count + 1)\nconsole.log(count)', result: '(prints the OLD value)', why: 'State is a snapshot for this render. The new value arrives on the next render.' },
    ],
    tips: ['Name the pair `[thing, setThing]`. Everyone reads it instantly.', 'Keep state minimal: store the items, derive the counts.', 'Lift state up: if two components need the same state, keep it in their closest shared parent and pass it down as props.'],
    related: ['props', 'react-events', 'use-effect', 'lists-keys', 'variable'],
  },
  'react-events': {
    term: 'Events in React (onClick, onChange…)', short: 'Pass a function to a camelCase prop like `onClick` and React calls it when the event happens.',
    what: 'In React you don\'t call `addEventListener`. You pass a function to a prop named after the event: `<button onClick={handlePack}>`. When the button is clicked, React calls your function with an event object. Usually the handler calls a state setter, which re-renders the screen.',
    how: '**The pattern:**\n```\nfunction handlePack() {\n  setPacked(packed + 1)\n}\n<button onClick={handlePack}>Pack</button>\n```\nor inline: `onClick={() => setPacked(packed + 1)}`\n\n**Pass the function, don\'t call it.** `onClick={handlePack}` ✓. `onClick={handlePack()}` ✗ calls it during render.\n**Need an argument?** Wrap it: `onClick={() => toggle(item.id)}`.\n\n**Common event props (camelCase):** `onClick`, `onChange` (in React it fires on **every keystroke** in a text box, like the DOM\'s `input` event), `onSubmit` (on a `<form>`), `onKeyDown`, `onFocus`, `onBlur`.\n\n**The event object:** `e.target` is the element, `e.target.value` the text in an input, `e.preventDefault()` cancels the default action (a form submit reloading the page).\n\n**Forms the React way:**\n```\n<form onSubmit={e => { e.preventDefault(); addItem() }}>\n  <input value={text} onChange={e => setText(e.target.value)} />\n  <button>Add</button>\n</form>\n```\n\n**Same accessibility rules as Camp III:** clickable things are `<button>`s (keyboard and screen reader support for free), and inputs get labels (`htmlFor` in JSX).\n\n**⛑️ In this game** the preview page is sandboxed and doesn\'t allow form submission, so tasks here use a button with `onClick` for adding. On a real site, wrapping inputs in a `<form>` with `onSubmit` is the better habit: Enter submits, too.',
    usage: [
      { code: '<button onClick={() => setPacked(packed + 1)}>Pack one</button>', out: '(each tap adds 1 and the screen updates)', note: 'Inline arrow function calling a setter.' },
      { code: '<input value={name} onChange={e => setName(e.target.value)} />\n<p>Hello, {name}</p>', out: '(the greeting updates as you type each letter)', note: 'onChange fires on every keystroke.' },
      { code: 'function GearItem({ item, onToggle }) {\n  return <button onClick={() => onToggle(item.id)}>{item.name}</button>\n}', note: 'A child reports a click to its parent through a function prop.' },
    ],
    uses: ['Buttons that change state: pack, add, delete, open, close.', 'Live inputs: search boxes, character counters, controlled forms.', 'Keyboard shortcuts with onKeyDown.'],
    when: ['Anything the user does should change what\'s on screen.'],
    whenNot: ['Don\'t attach `onClick` to a `<div>` to fake a button. Keyboard users can\'t reach or press it. Use `<button>`.', 'Don\'t use `addEventListener` on elements React renders. Use the event props; React removes and updates them for you.'],
    mistakes: [
      { wrong: '<button onclick={pack}>', result: 'Invalid event handler property `onclick`. Did you mean `onClick`?', why: 'React\'s development warning. Event props are camelCase.' },
      { wrong: '<button onClick={pack()}>', result: '(pack runs on every render; if it sets state: Too many re-renders.)', why: 'The brackets call it immediately. Pass `pack`, or `() => pack()`.' },
      { wrong: '<input value={name} />   (no onChange)', result: 'You provided a `value` prop to a form field without an `onChange` handler. This will render a read-only field…', why: 'A controlled input needs onChange to update its state, or the box can\'t be typed in.' },
    ],
    tips: ['Name handlers `handleX` and handler props `onX`: `<GearItem onToggle={handleToggle} />`.', 'Put a `console.log("clicked")` first in a handler when debugging: if it never prints, the prop isn\'t wired up.'],
    related: ['state', 'props', 'events', 'forms'],
  },
  'lists-keys': {
    term: 'Lists and keys', short: 'Turn an array into elements with `.map()`, and give each one a stable, unique `key`.',
    what: 'To show a list in React, you `.map()` an array of data into an array of JSX elements. Each element needs a **`key`** prop: a value that identifies that item among its siblings, like an ID number. Keys let React track which item is which when the list changes.',
    how: '```\n<ul>\n  {gear.map(item => (\n    <li key={item.id}>{item.name}</li>\n  ))}\n</ul>\n```\n• `.map()` returns a new array of `<li>`s; React renders arrays\n• `key` goes on the **outermost** element returned from the map (on `<GearItem key={…} />` if you map to components)\n• keys must be **unique among siblings** and **stable**: the same item keeps the same key forever\n• the best key is an id from your data (a database id, or one you create when adding: `Date.now()` or `crypto.randomUUID()`)\n\n**Why keys matter:** when the list changes, React matches old and new items by key. Good keys mean React moves, adds or removes exactly the right elements and keeps each item\'s state (a ticked checkbox, typed text) with the right item.\n\n**Why not the index?** `key={index}` works only if the list never reorders, filters or has items inserted. Delete the first item and every index shifts by one, so React thinks item 2 *is* item 1 and the wrong row can keep the wrong state.\n\n**Keys aren\'t props.** The component doesn\'t receive `key`. Pass the id separately if it needs it: `<GearItem key={item.id} id={item.id} />`.\n\n**Filtering and sorting:** `gear.filter(i => !i.packed).map(…)` shows a subset; the original state stays untouched. To sort, copy first: `[...gear].sort(…)`, because `.sort()` changes the array it\'s called on.',
    usage: [
      { code: 'const camps = [\n  { id: 1, name: "Base Camp" },\n  { id: 2, name: "Camp II" },\n]\nreturn <ul>{camps.map(c => <li key={c.id}>{c.name}</li>)}</ul>', out: '• Base Camp\n• Camp II', note: 'The everyday pattern.' },
      { code: '{gear.filter(i => i.packed).map(i => (\n  <GearItem key={i.id} item={i} />\n))}', note: 'Filter, then map. The key goes on the component.' },
      { code: '{gear.map(i => <li>{i.name}</li>)}   (no key)', out: 'Each child in a list should have a unique "key" prop.\n\nCheck the render method of `App`. See https://react.dev/link/warning-keys for more information.', note: 'Real React 19 development warning in the console. The list still shows; the bugs come later.' },
    ],
    uses: ['Any list from data: to-dos, messages, search results, products, gear.', 'Tables (map rows, and cells inside each row).'],
    when: ['You render an array. Every time.'],
    whenNot: ['Don\'t use `Math.random()` as a key: it changes every render, so React rebuilds every item and loses their state.', 'Avoid the array index as a key when items can be added, removed, filtered or reordered.'],
    mistakes: [
      { wrong: 'gear.map(i => <li>{i.name}</li>)', result: 'Each child in a list should have a unique "key" prop.', why: 'Add `key={i.id}` to the `<li>`.' },
      { wrong: 'gear.map(i => { <li key={i.id}>{i.name}</li> })', result: '(nothing renders, no error)', why: 'Curly braces after `=>` start a function body, which needs `return`. Use round brackets: `i => ( <li …> )`.' },
      { wrong: 'gear.push(newItem); setGear(gear)', result: '(the list doesn\'t update)', why: 'Same array. Use `setGear([...gear, newItem])`.' },
      { wrong: 'two items both with id: 3', result: 'Encountered two children with the same key, `3`. Keys should be unique so that components maintain their identity across updates. Non-unique keys may cause children to be duplicated and/or omitted — the behavior is unsupported and could change in a future version.', why: 'Duplicate keys confuse React\'s matching. Make ids unique.' },
    ],
    tips: ['Give every item an id when you create it, not when you render it.', 'If your data has no ids, that\'s the bug to fix, not the key.'],
    related: ['state', 'component', 'map-filter', 'array-methods'],
  },
  'use-effect': {
    term: 'Effects (useEffect)', short: 'Run code after React updates the screen, to sync with something outside React: the page title, a timer, a server.',
    what: '`useEffect` lets a component run code **after** it renders, to keep something outside React in sync with its state: the browser tab\'s title, a timer, a network connection, a subscription. Rendering must stay pure; effects are the official place for side effects that should happen because the component is on screen.',
    how: '```\nuseEffect(() => {\n  document.title = `${count} items packed`\n}, [count])\n```\n• **first argument:** a function, the effect. React runs it after the screen updates\n• **second argument, the dependency array:** which values the effect uses. React re-runs the effect only when one of them changed since the last render\n  • `[count]`: after the first render, then whenever count changes\n  • `[]`: once, after the first render (when the component appears)\n  • no array at all: after **every** render (rarely what you want)\n\n**Cleanup:** return a function from the effect to undo it. React runs the cleanup before re-running the effect and when the component disappears:\n```\nuseEffect(() => {\n  const id = setInterval(() => setSeconds(s => s + 1), 1000)\n  return () => clearInterval(id)\n}, [])\n```\nWithout cleanup, timers and connections pile up.\n\n**Development double-run:** with StrictMode (on by default in new projects), React mounts, cleans up, and mounts again in development, so an effect runs twice. If that breaks something, your cleanup is missing. Production runs it once.\n\n**You might not need an effect.** If you can calculate it from props or state, do it during render. Responding to a click? Do it in the click handler. Effects are for syncing with things **outside** React.\n\n**Fetching data:** an effect can fetch (with an `ignore` flag in the cleanup so a stale reply is dropped), but real projects usually use a framework\'s data loading or a data-fetching library.',
    usage: [
      { code: 'useEffect(() => {\n  document.title = `Packed: ${packed}`\n}, [packed])', out: '(the browser tab title updates whenever packed changes)', note: 'Syncing React state to something outside React.' },
      { code: 'useEffect(() => {\n  console.log("Camp mounted")\n  return () => console.log("Camp unmounted")\n}, [])', out: 'Camp mounted\nCamp unmounted\nCamp mounted', note: 'Real computer in development with StrictMode: mount, cleanup, mount again. In production, just "Camp mounted".' },
      { code: 'useEffect(() => {\n  const id = setInterval(() => setSeconds(s => s + 1), 1000)\n  return () => clearInterval(id)\n}, [])', note: 'A timer started once, stopped when the component goes away. The updater form avoids a stale `seconds`.' },
    ],
    uses: ['Setting the page title, or focusing an input when something opens.', 'Timers and intervals, with cleanup.', 'Connecting to and disconnecting from things: a chat server, a browser API, a third-party widget.'],
    when: ['Something outside React must match your component\'s state, and it should happen because the component is showing, not because of one specific click.'],
    whenNot: ['To compute values from state or props (a total, a filtered list). Compute during render.', 'To respond to a user action. Put that code in the event handler.', 'To copy props into state. Use the props directly.'],
    mistakes: [
      { wrong: 'useEffect(() => {\n  setCount(count + 1)\n})', result: 'Maximum update depth exceeded. This can happen when a component calls setState inside useEffect, but useEffect either doesn\'t have a dependency array, or one of the dependencies changes on every render.', why: 'No dependency array: render → effect sets state → render → effect… React logs this warning and the loop keeps spinning. Add the right dependencies, and question whether you need the effect at all.' },
      { wrong: 'useEffect(() => {\n  document.title = `Packed: ${packed}`\n}, [])', result: '(the title is set once and never updates)', why: 'The effect uses `packed` but doesn\'t list it, so it never re-runs. List every value the effect reads: `[packed]`. The React hooks lint rule catches this.' },
      { wrong: 'useEffect(() => { setInterval(tick, 1000) }, [])', result: '(two intervals in development, and a leak whenever the component unmounts)', why: 'No cleanup. Return `() => clearInterval(id)`.' },
      { wrong: 'useEffect(async () => { … }, [])', result: 'useEffect must not return anything besides a function, which is used for clean-up. (React goes on to explain: write the async function inside the effect and call it.)', why: 'An async function returns a promise, not a cleanup. Define an async function inside the effect and call it.' },
    ],
    tips: ['Read the dependency array as "re-sync when these change."', 'Add the React hooks lint rule `exhaustive-deps` (from eslint-plugin-react-hooks). The Vite React template\'s own linter only checks the rules of hooks, so it won\'t flag a missing dependency for you.', 'Before writing an effect, ask: "is this syncing with something outside React?" If not, you probably don\'t need one.'],
    related: ['state', 'react', 'promise', 'async-await'],
  },

  // ─────────────── Testing ───────────────
  testing: {
    term: 'Automated testing', short: 'Code that runs your code with known inputs and checks the answers, every time, in seconds.',
    what: '**Automated tests** are small programs that call your code and check the results. Instead of clicking around after every change ("does packing still work? does the total still add up?"), you run one command and every check runs in seconds, the same way every time. A failing test points at what broke before a user finds it.',
    how: 'Each test is a quick check you can run again after every change.\n\n**The shape of every test:** arrange (set up inputs), act (call the code), assert (check the result).\n\n**Kinds of tests, smallest to biggest:**\n• **unit tests** check one function or component on its own: fast, and you\'ll write the most of these\n• **integration tests** check pieces working together (your server plus a test database)\n• **end-to-end (E2E) tests** drive the real app in a browser like a user would: slow, but they test the whole app\n\n**Test runners** find your test files, run them, and report. Real ones you\'ll meet:\n• **node:test**: built into Node 18+. Run `node --test`\n• **Vitest**: a popular runner for Vite projects, with `expect` and fast re-runs as you save\n• **Jest**: an older, very widely used runner with the same `expect` style\n• **Playwright** (and others) for end-to-end browser tests\n\n**Coverage** measures which lines your tests *ran*. It shows what\'s untested; it doesn\'t prove the tested parts are right. A test with no assertion can "cover" a line and check nothing.\n\n**Tests run automatically** in real teams: on every push, a service runs the whole suite (this is called **CI**, continuous integration) and blocks merging if anything fails.\n\n**⛑️ In this game** a tiny built-in runner gives you `test(name, fn)` and `expect(value)` with `.toBe`, `.toEqual`, `.toBeTruthy`, `.toBeFalsy`, `.toContain` and `.toThrow`. Tests run after the rest of your code, each printing `✓ name` or `✗ name: reason`. Real runners print more detail, but the ideas are identical.',
    usage: [
      { code: 'function packWeight(items) {\n  return items.reduce((t, i) => t + i.kg, 0)\n}\ntest("adds up the pack", () => {\n  expect(packWeight([{ kg: 4 }, { kg: 1 }])).toBe(5)\n})', out: '✓ adds up the pack', note: 'In this game.' },
      { code: '$ node --test --test-reporter=spec', out: '✔ adds altitude gain (1.360547ms)\n✖ handles a zero gain (1.432789ms)\n  AssertionError [ERR_ASSERTION]: Expected values to be strictly equal:\n\n  7200 !== 7201\n…\nℹ tests 2\nℹ pass 1\nℹ fail 1', note: 'Real computer: Node\'s built-in runner (output trimmed).' },
      { code: '$ npx vitest run', out: ' Test Files  1 passed (1)\n      Tests  2 passed (2)', note: 'Real computer: Vitest in a Vite project (install with `npm install --save-dev vitest`).' },
    ],
    uses: ['Changing code without fear: the suite tells you within seconds if you broke something.', 'Pinning down a bug: write a test that reproduces it, fix it, and it can never silently come back.', 'Documenting behaviour: tests show exactly how a function is meant to be used.', 'Blocking broken code from being merged (CI).'],
    when: ['Logic that matters: money, permissions, calculations, data transformations.', 'Before changing (refactoring) code that already works.', 'Every time you fix a bug: first a test that fails because of it.'],
    whenNot: ['Don\'t test that the language works (`expect(1 + 1).toBe(2)`). Test YOUR code\'s decisions.', 'Don\'t chase 100% coverage as the goal. Meaningful checks on important behaviour beat touching every line.', 'Don\'t write tests so tied to internal details that every harmless rewrite breaks them. Test what the code does, not how.'],
    mistakes: [
      { prose: 'A test with no assertion: `test("works", () => { packWeight([]) })`.', why: 'It passes as long as nothing crashes, so it checks nothing. Every test needs at least one `expect`.' },
      { prose: 'Only testing the happy path.', why: 'Bugs often hide at the edges: empty lists, zero, negative numbers, missing fields, huge inputs. Write tests for those too.' },
      { prose: 'Never watching a test fail.', why: 'If you\'ve never seen it fail, you don\'t know it can. Break the code on purpose once and check the test catches it.' },
    ],
    tips: ['Name tests as sentences about behaviour: "an empty pack weighs nothing".', 'Run tests in watch mode (`npx vitest` without `run`) while you work: they re-run on every save.', 'A good suite is fast. Slow tests stop getting run.'],
    related: ['unit-test', 'assertion', 'test-first', 'edge-cases'],
  },
  'unit-test': {
    term: 'Unit test', short: 'A test of one small piece (a function or component) on its own, with a name that says what it proves.',
    what: 'A **unit test** checks one **unit** of code, usually a single function, in isolation: give it inputs, check its output. Unit tests are tiny, fast (milliseconds), and precise: when one fails, you know exactly which function and which case broke.',
    how: '**Anatomy (in this game, and in Vitest/Jest):**\n```\ntest("an empty pack weighs nothing", () => {\n  // arrange\n  const items = []\n  // act\n  const total = packWeight(items)\n  // assert\n  expect(total).toBe(0)\n})\n```\n• `test(name, fn)`: the name describes the behaviour; the function holds the check\n• one behaviour per test, so a failure tells a clear story\n\n**Picking cases:** a normal case, the edges (zero, empty, one item, the exact boundary like "exactly 8000 m"), and bad input (negative numbers, missing fields) if the function should handle them.\n\n**Pure functions are easiest to test**: same input, same output, no outside effects. That\'s one more reason to keep calculations out of event handlers and in their own functions.\n\n**Real files:** tests usually live next to the code: `gear.js` and `gear.test.js`. With node:test:\n```\nconst test = require("node:test")\nconst assert = require("node:assert")\ntest("adds altitude gain", () => {\n  assert.strictEqual(addAltitude(7200, 500), 7700)\n})\n```\n\n**React components** get unit tests too, with helper libraries that render a component and click it, much like this game\'s checks do.',
    usage: [
      { code: 'function isDeathZone(m) { return m >= 8000 }\n\ntest("8,000 m exactly is the death zone", () => {\n  expect(isDeathZone(8000)).toBe(true)\n})\ntest("7,999 m is not", () => {\n  expect(isDeathZone(7999)).toBe(false)\n})', out: '✓ 8,000 m exactly is the death zone\n✓ 7,999 m is not', note: 'Boundary cases: right at the line, and just below it.' },
      { code: 'test("packWeight ignores nothing", () => {\n  expect(packWeight([{ kg: 2 }, { kg: 3 }])).toBe(4)\n})', out: '✗ packWeight ignores nothing: expected 4 but got 5', note: 'A failing test in this game: the name, then what was expected and what came back. (Here the test itself was wrong; it happens. Read both sides.)' },
      { code: '// gear.test.js (real computer, Vitest)\nimport { test, expect } from "vitest"\nimport { packWeight } from "./gear.js"\n\ntest("an empty pack weighs 0", () => {\n  expect(packWeight([])).toBe(0)\n})', note: 'Same shape in a real project: import the function, then test it.' },
    ],
    uses: ['Calculations, formatting, validation, sorting, filtering: anything with clear inputs and outputs.', 'Locking in a bug fix so it can\'t come back.'],
    when: ['A function makes a decision or computes something.', 'You\'re about to change a function: write tests for what it does now, then change it safely.'],
    whenNot: ['When the "unit" is mostly gluing other things together (calling an API, saving to a database). Integration tests suit those better.', 'Don\'t cram ten behaviours into one test called "works". When it fails, you won\'t know which part broke.'],
    mistakes: [
      { prose: 'Tests that depend on each other (test 2 only passes if test 1 ran first).', why: 'Each test should set up its own data. Runners may run them in a different order or alone.' },
      { prose: 'Testing with the current date or random numbers.', why: 'The test passes today and fails tomorrow. Pass the date or the random value in as a parameter so tests can control it.' },
      { prose: 'Vague names like "test 1" or "it works".', why: 'When it fails in a list of 400, the name is all you see. Say what behaviour it proves.' },
    ],
    tips: ['If a function is hard to unit-test, it\'s often doing too much. Split the calculation out.', 'Copy the exact input from a bug report into a new test. That\'s the fastest way to reproduce it.'],
    related: ['testing', 'assertion', 'test-first', 'function'],
  },
  assertion: {
    term: 'Assertion (expect)', short: 'The line in a test that checks a value: "I expect this to be that." If it\'s false, the test fails.',
    what: 'An **assertion** is a check inside a test: `expect(actual).toBe(expected)`. If the check holds, nothing happens; if it doesn\'t, the assertion throws an error, the test fails, and the runner shows both values so you can see the difference.',
    how: '**Read it as a sentence:** `expect(packWeight([])).toBe(0)` = "I expect packWeight of an empty list to be 0."\n\n**Matchers (the part after the dot), in this game and in Vitest/Jest:**\n• `.toBe(x)`: exactly the same value (`Object.is`). Use for numbers, strings, booleans\n• `.toEqual(x)`: same **contents**. Use for arrays and objects. Two arrays with the same items are *not* `.toBe` each other, because they\'re different objects\n• `.toBeTruthy()` / `.toBeFalsy()`: truthy or falsy\n• `.toContain(x)`: an array or string includes x\n• `.toThrow()`: the function throws. Pass a **function**: `expect(() => ropeNeeded(-5)).toThrow()`\n\n**node:test style:** `assert.strictEqual(actual, expected)` and `assert.deepStrictEqual(a, b)` for objects.\n\n**Order matters for the message:** actual (what your code produced) goes in `expect(…)`; the expected value goes in the matcher.\n\n**Decimals:** `0.1 + 0.2` is `0.30000000000000004` in JavaScript, so `.toBe(0.3)` fails. Real runners have `.toBeCloseTo(0.3)`; or work in whole units (cents, metres).\n\n**In this game,** a failed assertion prints `✗ name: expected 0 but got 1` (or `expected something truthy but got 0`).',
    usage: [
      { code: 'test("rope count", () => {\n  expect(ropeNeeded(120)).toBe(3)\n})', out: '✓ rope count', note: 'A number compared with toBe.' },
      { code: 'test("packs a list", () => {\n  expect(pack(["rope"])).toEqual(["rope", "axe"])\n})', out: '✗ packs a list: expected [ \'rope\', \'axe\' ] but got [ \'rope\' ]', note: 'toEqual for arrays; the message shows both sides (this game).' },
      { code: 'test("rejects negative metres", () => {\n  expect(() => ropeNeeded(-5)).toThrow()\n})', out: '✓ rejects negative metres', note: 'toThrow needs a function to call, so wrap the call in `() =>`.' },
      { code: 'expect(["rope"]).toBe(["rope"])   (real Vitest)', out: 'AssertionError: expected [ \'rope\' ] to be [ \'rope\' ] // Object.is equality\n\nIf it should pass with deep equality, replace "toBe" with "toStrictEqual"', note: 'Real computer: two different arrays are never toBe each other.' },
    ],
    uses: ['Every test: an assertion is what turns "ran the code" into "proved the code".'],
    when: ['After every "act" step in a test. One clear behaviour per test, with as many assertions as that behaviour needs.'],
    whenNot: ['Don\'t assert on things that vary run to run (the current time, random ids) unless you control them.', 'Don\'t use `.toBeTruthy()` when you know the exact value. `expect(n).toBe(3)` catches more bugs than "something truthy".'],
    mistakes: [
      { wrong: 'expect(["rope"]).toBe(["rope"])', result: '✗ … expected [ \'rope\' ] but got [ \'rope\' ]', why: 'They look identical but are two different arrays. Use `.toEqual`.' },
      { wrong: 'expect(ropeNeeded(-5)).toThrow()', result: '(the error is thrown before expect even runs, so the test crashes)', why: 'Wrap it: `expect(() => ropeNeeded(-5)).toThrow()`. The matcher needs to call it itself.' },
      { wrong: 'expect(0.1 + 0.2).toBe(0.3)', result: 'expected 0.3 but got 0.30000000000000004', why: 'Decimal maths in binary isn\'t exact. Use `.toBeCloseTo` in a real runner, or whole numbers.' },
      { wrong: 'expect(packWeight(items))', result: '(passes, checks nothing)', why: 'An expect without a matcher asserts nothing. Finish it: `.toBe(5)`.' },
    ],
    tips: ['Write the assertion first, then the code that should make it pass.', 'When a test fails, read both values in the message before touching the code: sometimes the test is the one that\'s wrong.'],
    related: ['unit-test', 'testing', 'strict-equality', 'test-first'],
  },
  'test-first': {
    term: 'Test-first (test-driven development)', short: 'Write a failing test for the behaviour you want, then write just enough code to pass it, then tidy up. Red, green, refactor.',
    what: '**Test-first** development means writing the test **before** the code. You decide exactly what the function should do, write a test that checks it, watch it **fail** (red), write the simplest code that makes it **pass** (green), then clean up the code while the tests keep you safe (refactor). The formal name is **TDD**, test-driven development.',
    how: 'Decide what the code should do before you write it.\n\n**The loop:**\n1. **Red:** write one small test for the next behaviour. Run it. It must fail, and for the right reason (not a typo). A test you\'ve never seen fail proves nothing.\n2. **Green:** write the simplest code that passes. Not clever, not complete. Just passing.\n3. **Refactor:** improve names and structure. Re-run: still green? Good.\n4. Repeat with the next behaviour (the next edge case).\n\n**Example run:** "ropes needed for a distance, 50 m per rope"\n• test: `ropeNeeded(100)` is `2` → red (function doesn\'t exist)\n• code: `return metres / 50` → green\n• test: `ropeNeeded(120)` is `3` → red (got 2.4)\n• code: `return Math.ceil(metres / 50)` → green\n• test: negative metres throw → red\n• code: `if (metres < 0) throw new Error("metres must be positive")` → green\n\n**Why bother?**\n• you design the function from the caller\'s side first, so it\'s easy to use\n• every behaviour has a test from the moment it exists\n• you write only the code you need\n• fixing bugs test-first (a test that reproduces the bug first) means the bug can never return unnoticed',
    usage: [
      { code: '// 1. red: the test first\ntest("120 m needs 3 ropes", () => {\n  expect(ropeNeeded(120)).toBe(3)\n})\nfunction ropeNeeded(metres) {\n  return metres / 50\n}', out: '✗ 120 m needs 3 ropes: expected 3 but got 2.4', note: 'Red, for the right reason: the logic is incomplete.' },
      { code: '// 2. green: simplest code that passes\nfunction ropeNeeded(metres) {\n  return Math.ceil(metres / 50)\n}', out: '✓ 120 m needs 3 ropes', note: 'Math.ceil rounds up: 2.4 → 3.' },
      { code: '$ npx vitest\n(watch mode: re-runs the tests every time you save)', note: 'Real computer: the red-green loop with instant feedback.' },
    ],
    uses: ['Logic with clear rules: prices, discounts, permissions, validation, unit conversions.', 'Bug fixes: reproduce with a failing test, then fix.', 'Designing a function\'s interface before committing to how it works.'],
    when: ['You know what the code should do before you know how.', 'Fixing any bug that matters.', 'Code where a mistake is expensive (money, safety, security).'],
    whenNot: ['Exploring an idea you\'ll probably throw away (a "spike"). Explore first, then write tests for the version you keep.', 'Pure visual layout and styling, where you judge by eye. (Check the logic behind it test-first; check the look yourself.)'],
    mistakes: [
      { prose: 'Writing the test, never running it before the code, and seeing it pass.', why: 'Maybe it would have passed anyway (it checks nothing). Always see red first.' },
      { prose: 'Writing all twenty tests up front, then all the code.', why: 'One test at a time keeps each step small and each failure obvious.' },
      { prose: 'Changing the test to match buggy output.', why: 'The test is the spec. If the code disagrees, fix the code (unless the spec itself was wrong, and then say so).' },
    ],
    tips: ['Start with the simplest case (zero, empty), then add one rule per test.', 'Keep the red step quick: if a new test needs a lot of code to pass, write a smaller test.'],
    related: ['unit-test', 'assertion', 'testing', 'debugging-process'],
  },
  'static-typing': {
    term: 'Static and dynamic typing', short: 'Static typing checks value types before the program runs. Dynamic typing checks them while it runs.',
    what: 'Every value has a type: number, text, list and so on. The two styles differ in **when** the language checks that you used each value correctly.\n\n**Dynamic typing** (JavaScript, Python): types are checked only while the program runs. A mistake stays hidden until that exact line runs, and then it shows up as a crash or a strange result, maybe in front of a real user.\n\n**Static typing** (TypeScript, Java, Go, Rust): types are checked before the program runs. Many mistakes turn into errors in your editor while you type.',
    how: '**Dynamic:** `"5" * undefined` is not an error in JavaScript. It quietly gives `NaN` ("not a number"), and that `NaN` can travel through your code until a screen shows "NaN feet." You find out when someone sees it.\n\n**Static:** a checker reads your code without running it and follows each value. If a `string` goes where a `number` is expected, you get an error right away, with the file and line.\n\n**Type inference:** you do not have to label everything. The checker often works the type out itself. `let n = 5` is already a `number`, so `n = "five"` is an error with no label written.\n\n**TypeScript is JavaScript with a static checker added.** The types are **erased** when it is turned into JavaScript, so they do not exist while the program runs. That means they cannot check data that arrives at run time, such as an API reply or a form field. A reply typed as a number can still turn out to be text. Check that kind of data separately when it arrives.\n\n**Neither style is "better" everywhere.** Static typing catches a whole class of mistakes early and helps editors autocomplete. Dynamic typing needs less typing and is quick for small scripts.',
    usage: [
      { code: 'let n = 5\nn = "five"', out: 'error TS2322: Type \'string\' is not assignable to type \'number\'.', note: 'Real TypeScript checker message. `n` was inferred as a number from the 5, so the text is refused before anything runs.' },
      { code: 'console.log("5" * undefined)', out: 'NaN', note: 'Plain JavaScript (dynamic): no error at all, just a wrong value that can spread.' },
    ],
    uses: ['Catching wrong arguments, typos in property names and missing values while you type.', 'Big projects where many people change the code: the checker flags every place a change breaks.', 'Editor help: accurate autocomplete and safe renaming.'],
    when: ['Code that will grow or be changed by several people.', 'Code where a runtime crash is costly.', 'Whenever you want mistakes shown in the editor instead of to your users.'],
    whenNot: ['Do not trust types for outside data. Types vanish before running, so validate input from APIs, files and forms when it arrives.', 'A tiny throwaway script may not be worth the setup.'],
    mistakes: [
      { prose: 'Assuming that because the code has types, data from an API must match them.', why: 'The types are erased before running. `const reply: Forecast = await res.json()` only tells the checker to trust the server. Validate the data yourself.' },
      { prose: 'Thinking dynamic typing means "no types."', why: 'Values still have types. They are just checked late, while the program runs.' },
    ],
    tips: ['Hover over a variable in your editor to see the type the checker worked out.', 'Let inference do the easy cases and write types where the checker cannot guess, like function parameters.'],
    related: ['typescript', 'type-annotation', 'type-errors', 'union-type'],
  },
  immutability: {
    term: 'Immutability', short: 'Not changing existing data. Make a new copy with the change instead.',
    what: '**Immutable** means "does not change." Working immutably means you never edit a list or object in place. You build a **new** one that has the change in it and use that instead.\n\nIn React this is a rule, not just a style: **state must be replaced, not mutated.**',
    how: '**The React rule:** use `setGear([...gear, item])`, not `gear.push(item)`.\n\nReact decides whether to re-render by comparing the old state with the new state **by reference** (are they the very same object in memory? see the reference card). `push` changes the array but it is still the same array, so the reference is unchanged and React may not update the screen. `[...gear, item]` builds a new array, a new reference, so React sees a change.\n\n**Copying with the spread syntax `...`:**\n• add to a list: `[...gear, item]`\n• remove from a list: `gear.filter((g) => g !== item)`\n• change an object: `{ ...climber, camp: 3 }` copies every property and then sets `camp` to 3\n\n**Nested data:** the spread makes a **shallow** copy, one level deep. To change something inside, copy each level you touch: `{ ...climber, pack: [...climber.pack, "rope"] }`.\n\n**Why it helps beyond React:**\n• easier to reason about, because nothing changes behind your back\n• safe to share the same data in many places\n• old versions stay around, which makes undo and history possible',
    usage: [
      { code: 'const a = ["rope"]\nconst b = a\nb.push("axe")\nconsole.log(a === b, a)', out: 'true [ \'rope\', \'axe\' ]', note: 'Real Node output. push changed the array in place: b is the same array as a, so the comparison is true and a changed too. React would see no new reference.' },
      { code: 'const a = ["rope", "axe"]\nconst c = [...a, "boots"]\nconsole.log(a === c, a, c)', out: 'false [ \'rope\', \'axe\' ] [ \'rope\', \'axe\', \'boots\' ]', note: 'Real Node output. The spread made a new array: the references differ, and the original is untouched.' },
      { code: 'const climber = { name: "Sam", camp: 2 }\nconst moved = { ...climber, camp: 3 }\nconsole.log(climber.camp, moved.camp)', out: '2 3', note: 'Same idea for objects: the original keeps camp 2.' },
    ],
    uses: ['Updating React state: lists, objects and anything inside them.', 'Undo and redo, where you keep older versions.', 'Sharing data safely between parts of a program.'],
    when: ['Every time you update React state that holds a list or an object.', 'When other code may still be holding the data you are about to change.'],
    whenNot: ['For a private local variable inside one function, plain mutation is fine, such as pushing onto a list you built and have not shared.', 'Not for huge data changed thousands of times a second without measuring first. Copying has a cost.'],
    mistakes: [
      { wrong: 'gear.push(item)\nsetGear(gear)', result: '(the screen may not update)', why: 'You passed back the same array, so React sees no change. Pass a new one: `setGear([...gear, item])`.' },
      { prose: 'Copying an object with the spread and then changing something inside a nested part.', why: 'The spread is shallow. The inner list or object is still shared with the original. Copy each level you change.' },
    ],
    tips: ['Ask: "did I build a new array or object, or did I edit the old one?"', 'Methods that return a new array (`map`, `filter`, `slice`) are safe for state. Methods that change in place (`push`, `splice`, `sort`) are not.'],
    related: ['state', 'reference', 'react-events', 'component'],
  },
  'test-pyramid': {
    term: 'The test pyramid', short: 'Many fast unit tests, fewer integration tests, and a few end-to-end tests.',
    what: 'The **test pyramid** is a rule of thumb for how many tests of each kind to have. Picture a pyramid: a wide base of small, fast tests, a narrower middle, and a small tip of big, slow tests.',
    how: '**Bottom: unit tests (many).** Each checks one function on its own. They take milliseconds, so you can run thousands in seconds. When one fails, you know exactly where to look.\n\n**Middle: integration tests (fewer).** Each checks several parts working together, for example a route on your server talking to a test database. Slower, and they catch problems between the parts.\n\n**Top: end-to-end tests (a few).** Each drives a real browser that clicks through the app like a user. They test the whole thing, but they are slow and more fragile, because a small page change can break them.\n\n**Why a pyramid:** fast tests give quick, precise feedback, so you want lots of them. Big tests give the most confidence per test, but cost more to run and maintain, so you keep only the important journeys, like "sign up and place an order."\n\n**Run them automatically.** Real teams run the whole suite on every push. This is **continuous integration** (**CI**). A broken change is caught and blocked before it ships.',
    usage: [
      { code: '// gear.test.mjs\nimport test from \'node:test\'\nimport assert from \'node:assert\'\nfunction toFeet(m) { return Math.round(m * 3.28084) }\ntest(\'converts metres to feet\', () => {\n  assert.strictEqual(toFeet(8849), 29032)\n})', out: '✔ converts metres to feet (2.583984ms)\nℹ tests 1\nℹ pass 1\nℹ fail 0', note: 'Real `node --test --test-reporter=spec` output (trimmed). This is a unit test, the bottom layer: one function, checked in a few milliseconds.' },
      { code: 'unit         many   one function, milliseconds each\nintegration  some   a route plus a test database\nend-to-end   few    a real browser clicking through', note: 'Where each layer sits. Wide at the bottom, narrow at the top.' },
    ],
    uses: ['Deciding where to spend testing effort.', 'Keeping a suite that runs fast enough that people actually run it.', 'Setting up CI so a broken change is stopped before it ships.'],
    when: ['Planning tests for a new project.', 'When your suite has become slow or breaks for no clear reason. You may have too many big tests and too few small ones.'],
    whenNot: ['Do not treat the proportions as a law. They are a guide, and some apps need more integration tests than unit tests.', 'Do not skip the top layer entirely. A few end-to-end tests of the key journeys are worth having.'],
    mistakes: [
      { prose: 'Writing mostly end-to-end tests.', why: 'They are slow and fragile, so people stop running them and stop trusting them. Push checks down to unit tests where you can.' },
      { prose: 'Having tests but only running them by hand.', why: 'Forgotten tests protect nothing. Run them on every push with CI so a broken change is caught before it ships.' },
    ],
    tips: ['When an end-to-end test fails, try to write a smaller test that reproduces the same bug, then keep that one.', 'Keep unit tests so fast that you can run them every time you save.'],
    related: ['testing', 'unit-test', 'assertion', 'test-first'],
  },
}
